keyframes.cssText:
@keyframes underline-fill-forward { 
  0% { transform-origin: 0px center; transform: scaleX(0); }
  100% { transform-origin: 0px center; transform: scaleX(1); }
}

@keyframes underline-clear-forward { 
  0% { transform-origin: 100% center; transform: scaleX(1); }
  100% { transform-origin: 100% center; transform: scaleX(0); }
}
